// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    PrivateBank c;
    function setUp() public { c = new PrivateBank(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, c.MinDeposit(), uint256(1e30));
        vm.deal(actor, amount);

        vm.prank(actor);
        c.Deposit{value: amount}();

        uint256 before = c.balances(actor);
        vm.assume(before >= amount);

        vm.prank(actor);
        (bool ok,) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", amount));
        assertTrue(!ok || c.balances(actor) <= before, "CashOut must not increase caller balance");
    }
}
